package com.voicetxt.reader;

import android.app.*;import android.content.*;import android.os.*;import android.media.MediaMetadata;import android.media.session.*;import java.util.Locale;

/** Source-position media controls; no free-running/fictitious audio timeline. */
public final class PlaybackService extends Service {
    static final String CHANNEL="book_playback",PAUSE="com.voicetxt.reader.PAUSE",PLAY="com.voicetxt.reader.PLAY",PREVIOUS="com.voicetxt.reader.PREVIOUS",NEXT="com.voicetxt.reader.NEXT",STOP="com.voicetxt.reader.STOP";
    interface Host {void focusReady();void interrupted(String reason);void play();void pause();void stop();void previous();void next();void seek(float fraction);ReadingMediaState state();}
    static volatile PlaybackService active;static Host host;static Activity owner;static long hostVersion;long ownedVersion=-1;
    AudioGuard audioGuard;PowerManager.WakeLock wake;MediaSession session;boolean foreground;Intent readerIntent;ReadingMediaState state;long lastStateAt,lastNotificationAt;String lastMetadata="";
    static void begin(Activity activity,Host controls){if(owner!=null&&owner!=activity&&host!=null)host.pause();owner=activity;host=controls;long version=++hostVersion;Intent intent=new Intent(activity,PlaybackService.class).putExtra("playback_version",version).putExtra("reader",new Intent(activity.getIntent()).setClass(activity,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP));try{if(active==null||!active.foreground)activity.startForegroundService(intent);else activity.startService(intent);}catch(RuntimeException error){if(host==controls){host=null;owner=null;}throw error;}}
    static MainActivity reader(){return owner instanceof MainActivity&&!owner.isFinishing()&&!((MainActivity)owner).destroyed?(MainActivity)owner:null;}
    static void voiceSelected(String language,String key){MainActivity reader=reader();if(reader!=null&&reader.playing)reader.requestVoiceChange(key,language);}
    static void end(Context context){if(context instanceof Activity&&owner!=null&&owner!=context)return;hostVersion++;host=null;owner=null;if(active!=null&&active.audioGuard!=null)active.audioGuard.close();context.stopService(new Intent(context,PlaybackService.class));PlaybackBubble.refresh();}
    static void refreshActive(boolean force){PlaybackService service=active;if(service!=null)service.refresh(force);}
    @Override public void onConfigurationChanged(android.content.res.Configuration config){super.onConfigurationChanged(config);lastMetadata="";refresh(true);}
    @Override public void onCreate(){super.onCreate();active=this;audioGuard=new AudioGuard(this,reason->{if(active!=this||ownedVersion!=hostVersion)return;Host target=host;if(target!=null){target.interrupted(reason);parkPaused();}});NotificationChannel channel=new NotificationChannel(CHANNEL,getString(R.string.ui_139),NotificationManager.IMPORTANCE_LOW);channel.setSound(null,null);getSystemService(NotificationManager.class).createNotificationChannel(channel);
        wake=getSystemService(PowerManager.class).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"voicetxt:reading");wake.setReferenceCounted(false);wake.acquire(10000);
        session=new MediaSession(this,getString(R.string.ui_13));session.setFlags(MediaSession.FLAG_HANDLES_MEDIA_BUTTONS|MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS);session.setPlaybackToLocal(new android.media.AudioAttributes.Builder().setUsage(android.media.AudioAttributes.USAGE_MEDIA).setContentType(android.media.AudioAttributes.CONTENT_TYPE_SPEECH).build());session.setCallback(new MediaSession.Callback(){@Override public void onPlay(){action(PLAY);}@Override public void onPause(){action(PAUSE);}@Override public void onStop(){action(STOP);}@Override public void onSkipToPrevious(){action(PREVIOUS);}@Override public void onSkipToNext(){action(NEXT);}@Override public void onSeekTo(long position){Host target=host;if(target!=null&&state!=null){target.seek(Math.max(0,Math.min(1,(float)position/state.durationMs)));refresh(true);}}});Bundle slots=new Bundle();slots.putBoolean("android.media.playback.ALWAYS_RESERVE_SPACE_FOR.ACTION_SKIP_TO_PREVIOUS",true);slots.putBoolean("android.media.playback.ALWAYS_RESERVE_SPACE_FOR.ACTION_SKIP_TO_NEXT",true);session.setExtras(slots);session.setActive(true);
        state=new ReadingMediaState(getString(R.string.ui_13),getString(R.string.ui_140),0,0,1000,true,false,false);startForeground(41,notification());foreground=true;
    }
    PendingIntent command(String action,int request){return PendingIntent.getService(this,request,new Intent(this,PlaybackService.class).setAction(action),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    Notification notification(){Intent reader=readerIntent==null?new Intent(this,ShelfActivity.class):readerIntent;PendingIntent open=PendingIntent.getActivity(this,42,reader,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);String progress=String.format(AppLanguage.locale(this),getString(R.string.ui_141),state.fraction*100);
        return new Notification.Builder(this,CHANNEL).setSmallIcon(android.R.drawable.ic_media_play).setContentTitle(state.book).setContentText(state.chapter+" · "+progress).setSubText(getString(R.string.ui_13)).setContentIntent(open).setOngoing(state.playing).setOnlyAlertOnce(true).setVisibility(Notification.VISIBILITY_PUBLIC).setCategory(Notification.CATEGORY_TRANSPORT).setProgress(1000,Math.round(state.fraction*1000),false).addAction(new Notification.Action.Builder(android.R.drawable.ic_media_previous,getString(R.string.ui_25),command(PREVIOUS,43)).build()).addAction(new Notification.Action.Builder(state.playing?android.R.drawable.ic_media_pause:android.R.drawable.ic_media_play,state.playing?getString(R.string.ui_142):getString(R.string.ui_143),command(state.playing?PAUSE:PLAY,44)).build()).addAction(new Notification.Action.Builder(android.R.drawable.ic_media_next,getString(R.string.ui_27),command(NEXT,45)).build()).setDeleteIntent(command(STOP,46)).setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0,1,2)).build();
    }
    void refresh(boolean force){PlaybackBubble.refresh();if(host==null||session==null)return;long now=SystemClock.elapsedRealtime();if(!force&&now-lastStateAt<1000)return;lastStateAt=now;ReadingMediaState next=host.state();if(next==null)return;boolean changed=state==null||state.chapterIndex!=next.chapterIndex||state.playing!=next.playing;state=next;
        long actions=PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_PLAY_PAUSE|PlaybackState.ACTION_STOP|PlaybackState.ACTION_SEEK_TO;if(state.previous)actions|=PlaybackState.ACTION_SKIP_TO_PREVIOUS;if(state.next)actions|=PlaybackState.ACTION_SKIP_TO_NEXT;
        session.setPlaybackState(new PlaybackState.Builder().setActions(actions).setState(state.playing?PlaybackState.STATE_PLAYING:PlaybackState.STATE_PAUSED,state.positionMs(),0f,now).build());
        if(force||changed||now-lastNotificationAt>=5000){String label=String.format(AppLanguage.locale(this),getString(R.string.ui_144),state.fraction*100,state.chapter);String metadata=state.book+label+state.durationMs;if(!metadata.equals(lastMetadata)){session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,state.book).putString(MediaMetadata.METADATA_KEY_DISPLAY_TITLE,state.book).putString(MediaMetadata.METADATA_KEY_ARTIST,label).putString(MediaMetadata.METADATA_KEY_DISPLAY_SUBTITLE,label).putString(MediaMetadata.METADATA_KEY_ALBUM,state.chapter).putLong(MediaMetadata.METADATA_KEY_DURATION,state.durationMs).build());lastMetadata=metadata;}lastNotificationAt=now;getSystemService(NotificationManager.class).notify(41,notification());}
        // Promotion belongs to onStartCommand after the foreground-service start is delivered.
        // UI refresh may run first while the reader Activity is in the background.
    }
    void parkPaused(){audioGuard.close();refresh(true);if(wake!=null&&wake.isHeld())wake.release();stopForeground(STOP_FOREGROUND_DETACH);foreground=false;getSystemService(NotificationManager.class).notify(41,notification());}
    void action(String action){if(active!=this)return;Host target=host;if(target==null){stopSelf();return;}if(PAUSE.equals(action)){target.pause();parkPaused();}else if(PLAY.equals(action)){target.play();refresh(true);}else if(PREVIOUS.equals(action)){target.previous();refresh(true);}else if(NEXT.equals(action)){target.next();refresh(true);}else if(STOP.equals(action)){target.stop();stopSelf();}}
    @Override public int onStartCommand(Intent intent,int flags,int id){if(intent!=null&&intent.getAction()!=null){action(intent.getAction());return START_NOT_STICKY;}ownedVersion=intent==null?hostVersion:intent.getLongExtra("playback_version",hostVersion);if(ownedVersion!=hostVersion){startForeground(41,notification());foreground=true;return START_NOT_STICKY;}if(intent!=null){Intent reader=intent.getParcelableExtra("reader");if(reader!=null)readerIntent=reader;}startForeground(41,notification());foreground=true;refresh(true);if(host==null)stopSelf();else if(host.state().playing){if(audioGuard.acquire())host.focusReady();else{host.interrupted(getString(R.string.ui_145));parkPaused();}}return START_NOT_STICKY;}
    @Override public IBinder onBind(Intent intent){return null;}
    @Override public void onDestroy(){if(audioGuard!=null)audioGuard.close();if(active==this)active=null;if(ownedVersion==hostVersion){host=null;owner=null;}if(wake!=null&&wake.isHeld())wake.release();if(session!=null){session.setActive(false);session.release();}stopForeground(STOP_FOREGROUND_REMOVE);PlaybackBubble.refresh();super.onDestroy();}
}

